<?php
/**
 * Webhook diagnostics.
 *
 * Safety rules:
 * - Requests go only to the integration's own webhook URL, generated by the site and
 *   verified with Security::is_own_site_url(). No user-supplied URL is ever requested.
 * - The reachability probe is an unsigned POST. A correct handler rejects or ignores it.
 * - The signed test event (manual only, not part of the full run) uses the event name
 *   "pihc.diagnostic_ping", which no Paystack integration acts on. It never imitates
 *   charge.success, so it cannot mark orders paid or trigger fulfilment.
 * - Loopback results show the handler responds on this server; they cannot prove that
 *   Paystack's servers can reach it, and the UI says so.
 *
 * Expected responses (from the integrations' source):
 *   REST (pwcg)       unsigned -> 401; signed unknown event -> 200 {"reason":"unsupported_event"}
 *   wc-api (official) no handler hooked -> 400 (WooCommerce); unsigned or bad signature ->
 *                     200 with empty body (handler exits); valid signature, non-payment
 *                     event -> 200 with body "-1" (handler returns, WooCommerce prints -1)
 *
 * @package PaystackHealthChecker
 */

namespace PaystackHealthChecker\Checks;

use PaystackHealthChecker\Check_Definition;
use PaystackHealthChecker\Diagnostic_Context;
use PaystackHealthChecker\Diagnostic_Registry;
use PaystackHealthChecker\Diagnostic_Result;
use PaystackHealthChecker\Integrations\Integration_Adapter;
use PaystackHealthChecker\Log_Inspector;
use PaystackHealthChecker\Redactor;
use PaystackHealthChecker\Security;

defined( 'ABSPATH' ) || exit;

/**
 * Webhook checks.
 */
final class Webhook_Checks {

	public const DOC_WEBHOOKS = 'https://paystack.com/docs/payments/webhooks/';
	public const TEST_EVENT   = 'pihc.diagnostic_ping';
	public const TIMEOUT      = 15;

	/**
	 * Registers the checks.
	 *
	 * @param Diagnostic_Registry $registry Registry.
	 */
	public static function register( Diagnostic_Registry $registry ): void {
		$webhook = array( Diagnostic_Context::REQUIRES_INTEGRATION, Diagnostic_Context::REQUIRES_WEBHOOK_URL );
		$checks  = array(
			array( 'webhook.url', __( 'Webhook URL', 'paystack-integration-health-checker' ), __( 'The webhook URL to set in the Paystack dashboard can be generated and uses HTTPS.', 'paystack-integration-health-checker' ), 'url', $webhook, true, false ),
			array( 'webhook.handler_registered', __( 'Webhook handler registered', 'paystack-integration-health-checker' ), __( 'The integration\'s webhook handler is hooked into WordPress on this site.', 'paystack-integration-health-checker' ), 'handler_registered', $webhook, true, false ),
			array( 'webhook.endpoint_reachable', __( 'Webhook endpoint responds (loopback)', 'paystack-integration-health-checker' ), __( 'Sends an unsigned, non-payment POST from this server to its own webhook URL and interprets the response.', 'paystack-integration-health-checker' ), 'endpoint_reachable', $webhook, true, true ),
			array( 'webhook.signature_enforced', __( 'Unsigned requests rejected', 'paystack-integration-health-checker' ), __( 'The handler rejects requests without a valid x-paystack-signature, where that is observable from outside.', 'paystack-integration-health-checker' ), 'signature_enforced', $webhook, true, true ),
			array( 'webhook.signed_test', __( 'Signed test event', 'paystack-integration-health-checker' ), __( 'Manual only: sends a correctly signed, non-payment test event to confirm the handler accepts the configured key. Cannot change orders.', 'paystack-integration-health-checker' ), 'signed_test', array_merge( $webhook, array( Diagnostic_Context::REQUIRES_SECRET_KEY ) ), false, true ),
			array( 'webhook.public_reachability', __( 'Public reachability', 'paystack-integration-health-checker' ), __( 'Whether the webhook host could be reachable from the internet (not localhost or a private network).', 'paystack-integration-health-checker' ), 'public_reachability', $webhook, true, false ),
			array( 'webhook.local_errors', __( 'Webhook errors in local logs', 'paystack-integration-health-checker' ), __( 'Recent webhook-related warnings and errors in the WooCommerce logs this integration writes.', 'paystack-integration-health-checker' ), 'local_errors', array( Diagnostic_Context::REQUIRES_INTEGRATION ), true, false ),
		);

		foreach ( $checks as $check ) {
			$registry->add(
				new Check_Definition(
					array(
						'id'          => $check[0],
						'name'        => $check[1],
						'category'    => Check_Definition::CATEGORY_WEBHOOKS,
						'description' => $check[2],
						'callback'    => array( __CLASS__, $check[3] ),
						'requires'    => $check[4],
						'in_full_run' => $check[5],
						'network'     => $check[6],
						'doc_url'     => self::DOC_WEBHOOKS,
					)
				)
			);
		}
	}

	/**
	 * Webhook URL.
	 *
	 * @param Diagnostic_Context $context Context.
	 */
	public static function url( Diagnostic_Context $context ): Diagnostic_Result {
		$adapter  = $context->adapter();
		$url      = (string) $adapter->webhook_url();
		$evidence = array(
			'webhook_url' => $url,
			'environment' => $adapter->mode(),
		);
		$steps    = array( __( 'In Paystack Dashboard > Settings > API Keys & Webhooks, set this exact URL as the webhook URL for each environment you use (test and live are configured separately).', 'paystack-integration-health-checker' ) );

		if ( ! wp_http_validate_url( $url ) && ! Security::is_own_site_url( $url ) ) {
			return Diagnostic_Result::fail(
				__( 'The webhook URL generated for this integration is not a valid URL.', 'paystack-integration-health-checker' ),
				array(
					'evidence' => $evidence,
					'kb'       => 'missing_webhooks',
				)
			);
		}

		if ( 'https' !== wp_parse_url( $url, PHP_URL_SCHEME ) ) {
			$details = array(
				'explanation' => __( 'Webhook events confirm payments; they should only be delivered over HTTPS.', 'paystack-integration-health-checker' ),
				'evidence'    => $evidence,
				'next_steps'  => array_merge( array( __( 'Enable HTTPS for the site, then use the https:// version of this URL.', 'paystack-integration-health-checker' ) ), $steps ),
				'kb'          => 'site_not_public',
			);
			return 'live' === $adapter->mode()
				? Diagnostic_Result::fail( __( 'The webhook URL uses HTTP while live mode is enabled.', 'paystack-integration-health-checker' ), $details )
				: Diagnostic_Result::warning( __( 'The webhook URL uses HTTP.', 'paystack-integration-health-checker' ), $details );
		}

		return Diagnostic_Result::pass(
			__( 'Webhook URL generated.', 'paystack-integration-health-checker' ),
			array(
				'explanation' => __( 'The health checker cannot read your Paystack dashboard, so it cannot confirm this URL is the one configured there.', 'paystack-integration-health-checker' ),
				'evidence'    => $evidence,
				'next_steps'  => $steps,
			)
		);
	}

	/**
	 * Handler registration.
	 *
	 * @param Diagnostic_Context $context Context.
	 */
	public static function handler_registered( Diagnostic_Context $context ): Diagnostic_Result {
		$adapter  = $context->adapter();
		$evidence = array(
			'handler_type' => Integration_Adapter::WEBHOOK_REST === $adapter->webhook_kind() ? 'REST API route' : 'WooCommerce wc-api action',
		);

		if ( ! $adapter->webhook_handler_registered() ) {
			return Diagnostic_Result::fail(
				__( 'The integration\'s webhook handler is not registered.', 'paystack-integration-health-checker' ),
				array(
					'explanation' => __( 'Webhook requests to the URL would not reach any code. This usually means the gateway plugin failed to load or is too old.', 'paystack-integration-health-checker' ),
					'evidence'    => $evidence,
					'next_steps'  => array( __( 'Deactivate and reactivate the gateway plugin; update it; check "Integration errors in WooCommerce logs" for fatal errors.', 'paystack-integration-health-checker' ) ),
					'kb'          => 'missing_webhooks',
				)
			);
		}

		return Diagnostic_Result::pass( __( 'The webhook handler is registered.', 'paystack-integration-health-checker' ), array( 'evidence' => $evidence ) );
	}

	/**
	 * Unsigned loopback probe (shared by two checks; one request per run).
	 *
	 * @param Diagnostic_Context $context Context.
	 * @return array{ok:bool,status:int,body:string,elapsed_ms:int,error:string,location:string}|null Null when the URL is not this site.
	 */
	public static function unsigned_probe( Diagnostic_Context $context ): ?array {
		return $context->remember(
			'webhook.unsigned_probe',
			static function () use ( $context ) {
				$url = (string) $context->adapter()->webhook_url();
				if ( ! Security::is_own_site_url( $url ) ) {
					return null;
				}
				return self::post( $url, (string) wp_json_encode( array( 'event' => 'pihc.reachability_probe' ) ), array() );
			}
		);
	}

	/**
	 * Endpoint reachability.
	 *
	 * @param Diagnostic_Context $context Context.
	 */
	public static function endpoint_reachable( Diagnostic_Context $context ): Diagnostic_Result {
		$probe = self::unsigned_probe( $context );
		if ( null === $probe ) {
			return Diagnostic_Result::skipped( __( 'The webhook URL does not point to this site, so it was not requested.', 'paystack-integration-health-checker' ) );
		}

		$kind     = $context->adapter()->webhook_kind();
		$evidence = self::probe_evidence( $probe );
		$caveat   = __( 'This request was sent from the server to itself. A response shows the handler runs; it does not prove Paystack\'s servers can reach the URL (DNS, firewalls and CDNs can differ), and it does not prove a real event would be processed correctly.', 'paystack-integration-health-checker' );

		if ( ! $probe['ok'] ) {
			return Diagnostic_Result::warning(
				__( 'The site could not send a request to its own webhook URL.', 'paystack-integration-health-checker' ),
				array(
					'explanation' => __( 'Many hosts block loopback requests, so this is not proof the endpoint is broken for Paystack.', 'paystack-integration-health-checker' ) . ' ' . $caveat,
					'evidence'    => $evidence,
					'next_steps'  => array( __( 'Check the webhook delivery log in the Paystack dashboard for the real delivery status.', 'paystack-integration-health-checker' ) ),
					'kb'          => 'missing_webhooks',
				)
			);
		}

		$status = $probe['status'];
		if ( $status >= 300 && $status < 400 ) {
			return Diagnostic_Result::warning(
				/* translators: %d: HTTP status */
				sprintf( __( 'The webhook URL redirects (HTTP %d).', 'paystack-integration-health-checker' ), $status ),
				array(
					'explanation' => __( 'Webhook senders generally do not follow redirects for POST requests, so events may never reach the handler. Common causes: http-to-https or trailing-slash redirects.', 'paystack-integration-health-checker' ),
					'evidence'    => $evidence,
					'next_steps'  => array( __( 'Configure the final URL (see the redirect location) in the Paystack dashboard.', 'paystack-integration-health-checker' ) ),
					'kb'          => 'missing_webhooks',
				)
			);
		}
		if ( 404 === $status || ( Integration_Adapter::WEBHOOK_WC_API === $kind && 400 === $status ) ) {
			return Diagnostic_Result::fail(
				/* translators: %d: HTTP status */
				sprintf( __( 'The webhook URL returned HTTP %d: no handler answered.', 'paystack-integration-health-checker' ), $status ),
				array(
					'explanation' => Integration_Adapter::WEBHOOK_WC_API === $kind
						? __( 'WooCommerce returns 400 for wc-api requests when nothing is hooked to the endpoint.', 'paystack-integration-health-checker' )
						: __( 'The REST route was not found; permalinks or a security plugin may be blocking the REST API.', 'paystack-integration-health-checker' ),
					'evidence'    => $evidence,
					'next_steps'  => array( __( 'Check "Webhook handler registered" and whether the REST API is disabled by a plugin.', 'paystack-integration-health-checker' ) ),
					'kb'          => 'missing_webhooks',
				)
			);
		}
		if ( $status >= 500 ) {
			return Diagnostic_Result::fail(
				/* translators: %d: HTTP status */
				sprintf( __( 'The webhook handler returned a server error (HTTP %d).', 'paystack-integration-health-checker' ), $status ),
				array(
					'explanation' => __( 'A non-payment request caused a server error, which suggests the handler (or code running before it) is failing. Paystack would keep retrying real events.', 'paystack-integration-health-checker' ),
					'evidence'    => $evidence,
					'next_steps'  => array( __( 'Check the PHP error log and "Integration errors in WooCommerce logs".', 'paystack-integration-health-checker' ) ),
					'kb'          => 'order_not_updating',
				)
			);
		}
		if ( Integration_Adapter::WEBHOOK_WC_API === $kind && in_array( $status, array( 401, 403 ), true ) ) {
			return Diagnostic_Result::warning(
				/* translators: %d: HTTP status */
				sprintf( __( 'The request was blocked with HTTP %d before reaching the handler.', 'paystack-integration-health-checker' ), $status ),
				array(
					'explanation' => __( 'This integration\'s handler does not send 401/403 itself, so a security plugin, basic authentication or a firewall rule likely blocked the request. Paystack\'s deliveries may be blocked the same way.', 'paystack-integration-health-checker' ),
					'evidence'    => $evidence,
					'kb'          => 'missing_webhooks',
				)
			);
		}

		return Diagnostic_Result::pass(
			/* translators: %d: HTTP status */
			sprintf( __( 'The webhook endpoint responded on this server (HTTP %d).', 'paystack-integration-health-checker' ), $status ),
			array(
				'explanation' => $caveat,
				'evidence'    => $evidence,
			)
		);
	}

	/**
	 * Signature enforcement, where observable.
	 *
	 * @param Diagnostic_Context $context Context.
	 */
	public static function signature_enforced( Diagnostic_Context $context ): Diagnostic_Result {
		$kind = $context->adapter()->webhook_kind();

		if ( Integration_Adapter::WEBHOOK_WC_API === $kind ) {
			return Diagnostic_Result::skipped(
				__( 'Not observable for this integration.', 'paystack-integration-health-checker' ),
				array(
					'explanation' => __( 'This handler answers HTTP 200 with an empty body for both rejected and ignored requests, so enforcement cannot be seen from outside. Its source code (version 5.8.5) validates x-paystack-signature as HMAC-SHA512 of the raw body. Use "Signed test event" to confirm a correctly signed request is accepted.', 'paystack-integration-health-checker' ),
				)
			);
		}

		$probe = self::unsigned_probe( $context );
		if ( null === $probe || ! $probe['ok'] ) {
			return Diagnostic_Result::skipped( __( 'The loopback request did not complete, so enforcement could not be observed.', 'paystack-integration-health-checker' ) );
		}

		$evidence = self::probe_evidence( $probe );
		if ( 401 === $probe['status'] ) {
			return Diagnostic_Result::pass( __( 'The handler rejected an unsigned request (HTTP 401).', 'paystack-integration-health-checker' ), array( 'evidence' => $evidence ) );
		}
		if ( $probe['status'] >= 200 && $probe['status'] < 300 ) {
			return Diagnostic_Result::fail(
				__( 'The handler accepted a request without a signature.', 'paystack-integration-health-checker' ),
				array(
					'explanation' => __( 'Anyone could send fake events to this endpoint. Paystack signs every event with HMAC-SHA512 of the raw body using your secret key (x-paystack-signature header); handlers must verify it.', 'paystack-integration-health-checker' ),
					'evidence'    => $evidence,
					'kb'          => 'invalid_webhook_signature',
				)
			);
		}
		return Diagnostic_Result::skipped(
			/* translators: %d: HTTP status */
			sprintf( __( 'The response (HTTP %d) does not show whether signatures are enforced.', 'paystack-integration-health-checker' ), $probe['status'] ),
			array( 'evidence' => $evidence )
		);
	}

	/**
	 * Signed non-payment test event (manual only).
	 *
	 * @param Diagnostic_Context $context Context.
	 */
	public static function signed_test( Diagnostic_Context $context ): Diagnostic_Result {
		$adapter = $context->adapter();
		$url     = (string) $adapter->webhook_url();
		if ( ! Security::is_own_site_url( $url ) ) {
			return Diagnostic_Result::skipped( __( 'The webhook URL does not point to this site, so no test event was sent.', 'paystack-integration-health-checker' ) );
		}

		$body     = (string) wp_json_encode(
			array(
				'event' => self::TEST_EVENT,
				'data'  => array(
					'note' => 'Paystack Integration Health Checker diagnostic event. Not a payment.',
				),
			)
		);
		$probe    = self::post( $url, $body, array( 'x-paystack-signature' => hash_hmac( 'sha512', $body, $adapter->secret_key() ) ) );
		$evidence = array_merge(
			array(
				'event'       => self::TEST_EVENT,
				'environment' => $adapter->mode(),
			),
			self::probe_evidence( $probe )
		);

		if ( ! $probe['ok'] ) {
			return Diagnostic_Result::warning(
				__( 'The signed test event could not be delivered over loopback.', 'paystack-integration-health-checker' ),
				array(
					'explanation' => __( 'Many hosts block loopback requests; this does not prove Paystack cannot deliver events.', 'paystack-integration-health-checker' ),
					'evidence'    => $evidence,
					'kb'          => 'missing_webhooks',
				)
			);
		}

		$accepted = self::signed_event_accepted( $adapter->webhook_kind(), $probe );
		if ( true === $accepted ) {
			return Diagnostic_Result::pass(
				__( 'The handler accepted a correctly signed event and ignored it as a non-payment event.', 'paystack-integration-health-checker' ),
				array(
					'explanation' => __( 'Signature verification with the configured key works on this server and the raw request body reaches the handler intact. No order was changed.', 'paystack-integration-health-checker' ),
					'evidence'    => $evidence,
				)
			);
		}
		if ( false === $accepted ) {
			return Diagnostic_Result::fail(
				__( 'The handler rejected an event signed with the configured secret key.', 'paystack-integration-health-checker' ),
				array(
					'explanation' => __( 'The handler verifies signatures with a different key than the one the health checker reads (for example a key defined in wp-config.php), or something on the server modifies request bodies. Real Paystack events would be rejected the same way.', 'paystack-integration-health-checker' ),
					'evidence'    => $evidence,
					'next_steps'  => array( __( 'Make sure only one secret key is configured for this environment and that no plugin or proxy rewrites webhook bodies.', 'paystack-integration-health-checker' ) ),
					'kb'          => 'invalid_webhook_signature',
				)
			);
		}

		return Diagnostic_Result::warning(
			/* translators: %d: HTTP status */
			sprintf( __( 'Unexpected response to the signed test event (HTTP %d).', 'paystack-integration-health-checker' ), $probe['status'] ),
			array(
				'explanation' => __( 'The cause is unknown from this evidence.', 'paystack-integration-health-checker' ),
				'evidence'    => $evidence,
				'next_steps'  => array( __( 'Run "Webhook endpoint responds" and check the PHP error log.', 'paystack-integration-health-checker' ) ),
			)
		);
	}

	/**
	 * Public reachability (no external request is made).
	 *
	 * @param Diagnostic_Context $context Context.
	 */
	public static function public_reachability( Diagnostic_Context $context ): Diagnostic_Result {
		$url      = (string) $context->adapter()->webhook_url();
		$host     = (string) wp_parse_url( $url, PHP_URL_HOST );
		$private  = Security::host_is_private( $host );
		$evidence = array( 'host' => $host );

		if ( true === $private ) {
			return Diagnostic_Result::fail(
				__( 'The webhook host is local or private, so Paystack cannot reach it.', 'paystack-integration-health-checker' ),
				array(
					'explanation' => __( 'The host is localhost, a private-network address or a reserved local domain. Paystack\'s servers deliver webhooks over the public internet.', 'paystack-integration-health-checker' ),
					'evidence'    => $evidence,
					'next_steps'  => array( __( 'For local testing, expose the site through a tunnel with a public HTTPS URL and set that URL in the Paystack dashboard.', 'paystack-integration-health-checker' ) ),
					'kb'          => 'site_not_public',
				)
			);
		}
		if ( null === $private ) {
			return Diagnostic_Result::warning(
				__( 'The webhook host could not be resolved from this server.', 'paystack-integration-health-checker' ),
				array(
					'evidence' => $evidence,
					'kb'       => 'site_not_public',
				)
			);
		}

		return Diagnostic_Result::skipped(
			__( 'The host is public, but external reachability cannot be verified from inside the server.', 'paystack-integration-health-checker' ),
			array(
				'explanation' => __( 'Verifying it would require asking a third-party service to call the site, which this plugin deliberately does not do. Paystack\'s dashboard shows the result of each real delivery attempt.', 'paystack-integration-health-checker' ),
				'evidence'    => $evidence,
				'next_steps'  => array( __( 'Check the webhook delivery log in the Paystack dashboard.', 'paystack-integration-health-checker' ) ),
			)
		);
	}

	/**
	 * Webhook-related log errors.
	 *
	 * @param Diagnostic_Context $context Context.
	 */
	public static function local_errors( Diagnostic_Context $context ): Diagnostic_Result {
		$adapter   = $context->adapter();
		$inspector = new Log_Inspector( new Redactor( array( $adapter->secret_key(), $adapter->public_key() ) ) );

		if ( Log_Inspector::HANDLER_UNSUPPORTED === $inspector->handler() ) {
			return Diagnostic_Result::skipped( __( 'WooCommerce logs are not available through a supported handler.', 'paystack-integration-health-checker' ) );
		}

		$own   = $adapter->log_sources() ? $inspector->scan( $adapter->log_sources(), 7, '', '/webhook|signature/i' ) : null;
		$fatal = '' !== $adapter->log_marker() ? $inspector->scan( array( 'fatal-errors' ), 7, $adapter->log_marker() ) : null;

		if ( null === $own && null === $fatal ) {
			return Diagnostic_Result::skipped( __( 'This integration does not write logs the health checker knows how to read.', 'paystack-integration-health-checker' ) );
		}

		$errors   = (int) ( $own['errors'] ?? 0 ) + (int) ( $fatal['errors'] ?? 0 );
		$warnings = (int) ( $own['warnings'] ?? 0 );
		$evidence = array(
			'window'           => 'last 7 days',
			'sources'          => $adapter->log_sources() ? implode( ', ', $adapter->log_sources() ) : 'none (integration does not log)',
			'webhook_errors'   => $own['errors'] ?? 'n/a',
			'webhook_warnings' => $own['warnings'] ?? 'n/a',
			'fatal_errors'     => $fatal['errors'] ?? 'n/a',
			'excerpts'         => array_merge( $own['excerpts'] ?? array(), $fatal['excerpts'] ?? array() ),
		);

		if ( $errors + $warnings > 0 ) {
			return Diagnostic_Result::warning(
				/* translators: 1: errors, 2: warnings */
				sprintf( __( 'Found %1$d webhook-related errors and %2$d warnings in the last 7 days.', 'paystack-integration-health-checker' ), $errors, $warnings ),
				array(
					'explanation' => __( 'Log entries show something went wrong but not necessarily what caused it. Read the excerpts: signature failures point to key mismatches; unknown references can be other integrations on the same Paystack account.', 'paystack-integration-health-checker' ),
					'evidence'    => $evidence,
					'kb'          => 'invalid_webhook_signature',
				)
			);
		}

		return Diagnostic_Result::pass(
			__( 'No webhook-related errors or warnings were logged in the last 7 days.', 'paystack-integration-health-checker' ),
			array(
				'explanation' => null === $own ? __( 'This integration does not write to the WooCommerce log, so only fatal errors could be checked.', 'paystack-integration-health-checker' ) : '',
				'evidence'    => $evidence,
			)
		);
	}

	/**
	 * Interprets the signed test response.
	 *
	 * @param string                                                            $kind  Webhook kind.
	 * @param array{ok:bool,status:int,body:string,elapsed_ms:int,error:string} $probe Probe.
	 * @return bool|null True accepted, false rejected, null unknown.
	 */
	public static function signed_event_accepted( string $kind, array $probe ): ?bool {
		if ( Integration_Adapter::WEBHOOK_REST === $kind ) {
			if ( 401 === $probe['status'] ) {
				return false;
			}
			$json = json_decode( $probe['body'], true );
			return 200 === $probe['status'] && is_array( $json ) && isset( $json['reason'] ) ? true : null;
		}
		if ( Integration_Adapter::WEBHOOK_WC_API === $kind && 200 === $probe['status'] ) {
			$body = trim( $probe['body'] );
			if ( '-1' === $body ) {
				return true;
			}
			if ( '' === $body ) {
				return false;
			}
		}
		return null;
	}

	/**
	 * Sends a loopback POST to an own-site URL.
	 *
	 * @param string               $url     Own-site URL (validated by caller).
	 * @param string               $body    Raw body.
	 * @param array<string,string> $headers Extra headers.
	 * @return array{ok:bool,status:int,body:string,elapsed_ms:int,error:string,location:string}
	 */
	private static function post( string $url, string $body, array $headers ): array {
		$started  = microtime( true );
		$response = wp_remote_post(
			$url,
			array(
				'timeout'     => self::TIMEOUT,
				'redirection' => 0,
				/** This filter is documented in wp-includes/class-wp-http-streams.php */
				'sslverify'   => apply_filters( 'https_local_ssl_verify', false ), // phpcs:ignore WordPress.NamingConventions.PrefixAllGlobals.NonPrefixedHooknameFound -- Core filter for loopback requests.
				'headers'     => array_merge(
					array(
						'Content-Type'      => 'application/json',
						'User-Agent'        => 'PaystackIntegrationHealthChecker/' . PIHC_VERSION . ' (loopback diagnostic)',
						'X-PIHC-Diagnostic' => '1',
					),
					$headers
				),
				'body'        => $body,
			)
		);
		$elapsed  = (int) round( ( microtime( true ) - $started ) * 1000 );

		if ( is_wp_error( $response ) ) {
			return array(
				'ok'         => false,
				'status'     => 0,
				'body'       => '',
				'elapsed_ms' => $elapsed,
				'error'      => substr( $response->get_error_message(), 0, 200 ),
				'location'   => '',
			);
		}

		return array(
			'ok'         => true,
			'status'     => (int) wp_remote_retrieve_response_code( $response ),
			'body'       => substr( (string) wp_remote_retrieve_body( $response ), 0, 500 ),
			'elapsed_ms' => $elapsed,
			'error'      => '',
			'location'   => (string) wp_remote_retrieve_header( $response, 'location' ),
		);
	}

	/**
	 * Evidence for a probe.
	 *
	 * @param array<string,mixed> $probe Probe.
	 * @return array<string,mixed>
	 */
	private static function probe_evidence( array $probe ): array {
		$evidence = array(
			'http_status' => $probe['ok'] ? $probe['status'] : 'no response',
			'elapsed_ms'  => $probe['elapsed_ms'],
		);
		if ( '' !== $probe['error'] ) {
			$evidence['transport_error'] = $probe['error'];
		}
		if ( '' !== $probe['location'] ) {
			$evidence['redirect_location'] = $probe['location'];
		}
		if ( $probe['ok'] ) {
			$evidence['response_excerpt'] = '' === trim( $probe['body'] ) ? '(empty body)' : substr( wp_strip_all_tags( $probe['body'] ), 0, 160 );
		}
		return $evidence;
	}
}
